// Generates what Codex and other agents read from what Claude Code reads, so the two never drift apart:
//   AGENTS.md        = the preamble below + CLAUDE.md, verbatim
//   .agents/skills/  = a byte-for-byte copy of .claude/skills/
//   node scripts/sync-agents.mjs           writes them (yarn agents:sync)
//   node scripts/sync-agents.mjs --check   lists what is stale and exits 1 (scripts/__tests__/sync-agents.test.ts)
// Edit CLAUDE.md, .claude/skills/ or the preamble here, never the generated files.
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  realpathSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { dirname, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const PREAMBLE = `# AGENTS.md

<!-- Generated by \`yarn agents:sync\` (scripts/sync-agents.mjs) from CLAUDE.md. Edit CLAUDE.md or the preamble in that script, never this file: a test fails while it is stale. -->

Instructions for coding agents (Codex and others) working in this repository. The project rules are CLAUDE.md,
copied in full below so they load with this file; they apply to every agent alike.

- Commit messages follow [\`CONTRIBUTING.md\`「提交信息」](CONTRIBUTING.md): Chinese, subject「type(scope): 中文描述」
  (type: feat fix refactor docs test chore ci perf build), a \`文档:\` line in the body, \`git commit -s\`, and your own
  full \`Co-authored-by: Name <email>\` trailer at the end (Codex: \`Co-authored-by: Codex <noreply@openai.com>\`). The
  commit-msg and pre-push hooks in \`scripts/githooks/\` refuse anything else.
- Never deploy, run production migrations or push without a person saying so in the conversation.
- \`.agents/skills/\` is generated from \`.claude/skills/\` the same way: edit the \`.claude/skills/\` original.

---

`;

const SKILLS_FROM = '.claude/skills';
const SKILLS_TO = '.agents/skills';

const lf = (text) => text.replace(/\r\n/g, '\n');

/** Every file under `dir`, as paths relative to it with forward slashes. */
function filesUnder(dir) {
  if (!existsSync(dir)) return [];
  const out = [];
  const walk = (d) => {
    for (const e of readdirSync(d, { withFileTypes: true })) {
      const p = join(d, e.name);
      if (e.isDirectory()) walk(p);
      else out.push(relative(dir, p).split(sep).join('/'));
    }
  };
  walk(dir);
  return out.sort();
}

/** What the generated files should contain: repository-relative path → content. */
export function expectedFiles(root) {
  const files = new Map();
  files.set(
    'AGENTS.md',
    Buffer.from(PREAMBLE + lf(readFileSync(join(root, 'CLAUDE.md'), 'utf8')))
  );
  for (const f of filesUnder(join(root, SKILLS_FROM)))
    files.set(`${SKILLS_TO}/${f}`, readFileSync(join(root, SKILLS_FROM, f)));
  return files;
}

/**
 * Generated files that are missing, differ, or no longer have a source (sorted). Compared with line endings made
 * LF, so a checkout that converts them (core.autocrlf) is not stale.
 */
export function staleFiles(root) {
  const want = expectedFiles(root);
  const stale = [];
  for (const [path, content] of want) {
    const p = join(root, path);
    if (
      !existsSync(p) ||
      lf(readFileSync(p, 'utf8')) !== lf(content.toString('utf8'))
    )
      stale.push(path);
  }
  for (const f of filesUnder(join(root, SKILLS_TO)))
    if (!want.has(`${SKILLS_TO}/${f}`)) stale.push(`${SKILLS_TO}/${f}`);
  return stale.sort();
}

/** Writes the generated files and removes skill copies whose source is gone. Returns what changed. */
export function sync(root) {
  const stale = staleFiles(root);
  const want = expectedFiles(root);
  for (const path of stale) {
    const p = join(root, path);
    const content = want.get(path);
    if (content === undefined) rmSync(p);
    else {
      mkdirSync(dirname(p), { recursive: true });
      writeFileSync(p, content);
    }
  }
  return stale;
}

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const isMain =
  process.argv[1] !== undefined &&
  realpathSync(process.argv[1]) ===
    realpathSync(fileURLToPath(import.meta.url));
if (isMain) {
  if (process.argv.includes('--check')) {
    const stale = staleFiles(ROOT);
    if (stale.length) {
      console.error(
        `Stale, run \`yarn agents:sync\`:\n${stale.map((s) => `  ${s}`).join('\n')}`
      );
      process.exit(1);
    }
  } else {
    const changed = sync(ROOT);
    console.log(
      changed.length
        ? `Updated:\n${changed.map((s) => `  ${s}`).join('\n')}`
        : 'AGENTS.md and .agents/skills/ are up to date.'
    );
  }
}
